"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_text(value):
    return isinstance(value, str) and bool(value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        # `type(...) is not int` excludes bool, which is an int subclass.
        if (not isinstance(row, dict) or not _is_text(row.get("id"))
                or not _is_text(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": read_dependencies(row.get("depends_on")),
        })
    return changes


def read_dependencies(raw):
    if raw is None:
        return []
    if not isinstance(raw, list) or not all(_is_text(dep) for dep in raw):
        raise JournalError("invalid-change")
    # Deduplicate per record only; ordering is irrelevant because replay
    # identity compares dependency *sets*.
    return frozenset(raw)


def read_applied(raw):
    if raw is None:
        return []
    if not isinstance(raw, list) or not all(_is_text(entry) for entry in raw):
        raise JournalError("invalid-change")
    # The journal is caller-supplied state, so repeats are idempotent.
    return frozenset(raw)


def read_retain(raw):
    if raw is None:
        return frozenset()
    if not isinstance(raw, list) or not all(_is_text(entry) for entry in raw):
        raise JournalError("invalid-retain")
    # Repeats name the same retained change, so idempotent like the journal.
    return frozenset(raw)


def _identity(change):
    # Replay identity: dependencies are compared as a set (order-insensitive),
    # so two records differing only in depends_on order are the same record and
    # must be collapsed BEFORE accounting; otherwise units would double-count.
    return (change["id"], change["component"], change["units"], change["depends_on"])


def collapse(changes):
    """Collapse identical duplicates; reject conflicting reuse of one id.

    Identity lives here (not in planner) so accounting always sees one record
    per change ID and no code path can sum units twice.
    """
    unique = {}
    for change in changes:
        seen = unique.get(change["id"])
        if seen is None:
            unique[change["id"]] = change
        elif _identity(seen) != _identity(change):
            # Same id but different component/units/dependency set is ambiguous
            # history: fail closed rather than pick a winner.
            raise JournalError("conflicting-change")
    return unique


def retention(unique, applied, retain):
    """IDs that G2 staging rollback must keep, and their applied prerequisites.

    `retain` may only name changes that are already applied; anything else is a
    request to keep something that does not exist or was never released, so it
    is rejected as `invalid-retain`.  Dependency closure is taken from the
    applied prerequisite edges only, so a retained change never pulls in an
    unapplied change (which could not be "kept" anyway).
    """
    for change_id in retain:
        if change_id not in applied:
            raise JournalError("invalid-retain")
    kept = set()
    pending = list(retain)
    while pending:
        change_id = pending.pop()
        if change_id in kept:
            continue
        kept.add(change_id)
        for prerequisite in unique[change_id]["depends_on"]:
            if prerequisite in applied and prerequisite not in kept:
                pending.append(prerequisite)
    return kept

