"""Compose policy and journal data into a plan."""
import heapq

from journal import (
    JournalError,
    collapse,
    read_applied,
    read_changes,
    read_retain,
    retention,
)
from policy import PolicyError, freeze_check, limit_for, plan_cap


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(unique):
    """Deterministic order: eligible set pops the lexicographically smallest id.

    Graph direction: `depends_on` points from a change to its prerequisite, so
    an edge prerequisite -> dependent means "must run first". Edges are matched
    ID-for-ID against the collapsed record set, which is why an unknown target
    is reported before any ordering work.
    """
    waiting = {}
    dependents = {change_id: [] for change_id in unique}
    for change_id, change in unique.items():
        for prerequisite in change["depends_on"]:
            if prerequisite not in unique:
                raise JournalError("unknown-dependency")
            waiting[change_id] = waiting.get(change_id, 0) + 1
            dependents[prerequisite].append(change_id)

    ready = [change_id for change_id in unique if change_id not in waiting]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            waiting[dependent] -= 1
            if waiting[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(unique):
        # A self-loop or a cycle anywhere leaves nodes permanently blocked; the
        # whole request fails instead of returning the acyclic prefix.
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    # The production freeze is the first gate after the shape check: it must run
    # before graph/change validation so even a malformed production request
    # reports `production-frozen` (plan and rollback alike).
    try:
        freeze_check(request)
    except PolicyError as exc:
        return failure(str(exc))
    action = request.get("action")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        retain = read_retain(request.get("retain")) if action == "rollback" else frozenset()
        unique = collapse(changes)
        order = _topological_order(unique)
        for change_id in applied:
            # The journal is untrusted input too: an id absent from `changes`
            # cannot be replayed consistently, so fail closed.
            if change_id not in unique:
                raise JournalError("unknown-dependency")
        # Retained + transitively required applied IDs are computed after the
        # graph is known valid, so malformed requests still fail first.
        kept = retention(unique, applied, retain)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    # Replay filter happens before the budget check so already-applied units
    # neither count against `plan` nor get re-emitted.
    if action == "rollback":
        # Rollback walks the full deterministic order backwards (last-in,
        # first-out) and only touches applied changes.  Retained IDs and their
        # applied prerequisites stay in place; skipping them keeps the relative
        # reverse order of the remaining applied IDs.
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in kept]
    else:
        actions = [change_id for change_id in order if change_id not in applied]
        # The effective G2 budget is the smaller of the request budget and the
        # staging ceiling, so a request that permits more is still rejected.
        if sum(unique[change_id]["units"] for change_id in actions) > min(budget, plan_cap()):
            return failure("budget-exceeded")
    # Rollback returns before the cap: `budget` is validated, not enforced, there.
    return {
        "status": "ok",
        "actions": actions,
        "units": sum(unique[change_id]["units"] for change_id in actions),
    }

