"""Compose policy and journal data into a plan."""
from journal import JournalError, read_journal, read_retain
from policy import (PolicyError, check_budget, override_staging_quota,
                    limit_for)


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def check_targets(changes):
    """Reject dependencies naming unknown changes before any ordering.

    Without this, a missing target would still topologically sort (the edge just
    never appears), producing an order that looks valid but violates a dependency
    the caller declared. Unknown applied ids are rejected earlier in journal.py.
    """
    known = {row["id"] for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")


def topological_order(changes):
    """Kahn's algorithm with lexicographic tie-breaking among ready nodes.

    Edges point dependency -> dependant, so the result is a rollout order and its
    reverse is the only safe rollback order. Picking the smallest ready id makes
    the order a pure function of the records, so repeated requests replay the
    same journal identically. Any ordering is total, so leftover nodes mean a cycle.
    """
    # A plain count of graph nodes, not a units map: journal._identify has already
    # collapsed duplicates, so one row is one node and len(order) != total means
    # some node kept an unmet edge. Naming this "units" collided with the per-change
    # units field that later drives budget accounting.
    total = len(changes)
    ready = {row["id"] for row in changes if not row["depends_on"]}
    pending = {row["id"]: set(row["depends_on"]) for row in changes}
    order = []
    while ready:
        current = min(ready)
        ready.remove(current)
        order.append(current)
        # Rebuild readiness from remaining unmet dependencies only; self edges stay
        # unmet and therefore surface as dependency-cycle instead of hiding.
        for change_id, unmet in pending.items():
            if change_id == current or current not in unmet:
                continue
            unmet.discard(current)
            if not unmet:
                ready.add(change_id)
    if len(order) != total:
        raise JournalError("dependency-cycle")
    return order


def retention_closure(order, changes, retain):
    """Applied ids kept on rollback: retain plus its applied transitive deps.

    Edges point dependency -> dependant, so this walk goes the other way: from a
    retained change to the changes it depends on. A retained change cannot stay
    while something it needs is reverted, so every applied dependency reachable
    through depends_on must be kept too; skipping the closure would emit an
    order that leaves the retained change running on missing dependencies.
    Only applied ids are collected here; the caller filters output by applied.
    """
    by_id = {row["id"]: row for row in changes}
    kept = set()
    stack = list(retain)
    while stack:
        current = stack.pop()
        if current in kept or current not in by_id:
            continue
        kept.add(current)
        stack.extend(by_id[current]["depends_on"])
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # limit_for runs the environment gate first, so production-frozen wins
        # over every payload error, including a malformed graph.
        budget = limit_for(request)
        changes, applied = read_journal(request)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    try:
        check_targets(changes)
        order = topological_order(changes)
    except JournalError as exc:
        return failure(str(exc))
    action = request["action"]
    try:
        # Retain is validated after the graph so a broken graph still reports
        # its own error; it is read only for rollback and never affects plan.
        retain = read_retain(request, applied)
    except JournalError as exc:
        return failure(str(exc))
    by_id = {row["id"]: row for row in changes}
    if action == "rollback":
        # Only applied changes come down, latest-first within the full order;
        # unapplied changes keep their position but are never reverted. Retained
        # changes and their applied dependencies stay put, so filtering happens
        # on the original reverse order rather than a re-sorted remnant.
        held = retention_closure(order, changes, retain)
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in held]
    else:
        # Applied changes are already in the journal: they satisfy dependencies
        # without being emitted and without consuming new budget.
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(by_id[change_id]["units"] for change_id in actions)
