"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_changes, read_journal
from policy import PolicyError, authorize, budget_exceeds


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _graph(changes):
    """Build adjacency lists in execution direction: dependency -> dependents.

    Edge direction is the one non-obvious invariant of this module. A change's
    `depends_on` entries are prerequisites, so the edge points *out of* the
    prerequisite *into* the dependent; only a change whose prerequisites have all
    been emitted is eligible. Inverting the edge (dependent -> prerequisite) would
    silently produce a release order that runs dependents first.
    """
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            dependents[dependency].append(row["id"])
    return dependents


def _validate_graph(changes, applied):
    """Fail closed on dangling references before any ordering is attempted.

    A dependency or an `applied` entry naming an ID that is not declared in
    `changes` cannot be ordered or replayed, so it is `unknown-dependency`. This
    must run before cycle detection and before budget checks: an input that names
    unknown IDs is not plannable at all, regardless of how much budget is left.
    """
    known = {row["id"] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")


def topological_order(changes):
    """Return every change ID in deterministic execution order.

    Eligible changes are drained from a min-heap keyed by ID, so ties among
    currently eligible changes break lexicographically and the result depends
    only on the graph, not on input order. Cycles (including self-dependencies)
    leave nodes unemitted and fail with `dependency-cycle`.
    """
    dependents = _graph(changes)
    remaining = {row["id"]: len(set(row["depends_on"])) for row in changes}
    ready = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def _result(action, ids, units_by_id):
    return {
        "status": "ok",
        "actions": list(ids),
        "units": sum(units_by_id[change_id] for change_id in ids),
    }


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        _environment, action, budget = authorize(request)
        changes = read_changes(request.get("changes"))
        applied = read_journal(request.get("applied", []))
        # Replay identity is established by `read_changes` (duplicates collapsed);
        # from here on every change is distinct, so units are counted per change.
        _validate_graph(changes, applied)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if action == "rollback":
        # Reverse of the full deterministic order, filtered to the journal: a
        # change that was never released has nothing to unwind, and applied
        # changes still impose the unwind order on each other.
        targets = [change_id for change_id in reversed(order) if change_id in applied]
        return _result(action, targets, units_by_id)

    # Replay point: the journal is subtracted *before* budgeting. An applied
    # change satisfies its dependents' prerequisites and costs no new units, so
    # the budget only has to cover what is actually about to be released.
    targets = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in targets)
    # Checked only after replay: duplicating records must not double the demand,
    # and an applied change must not consume budget it will not spend.
    if budget_exceeds(action, units, budget):
        return failure("budget-exceeded")
    return _result(action, targets, units_by_id)

