    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")


def topological_order(changes):
    """Return every change ID in deterministic execution order.

    Eligible changes are drained from a min-heap keyed by ID, so ties among
    currently eligible changes break lexicographically and the result depends
    only on the graph, not on input order. Cycles (including self-dependencies)
    leave nodes unemitted and fail with `dependency-cycle`.
    """
