    remaining = {row["id"]: len(set(row["depends_on"])) for row in changes}
    ready = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def _retained(order, applied, retain, prerequisites):
    """Return the applied IDs a rollback must keep.

    A retained change is only safe to stay installed if the prerequisites it still
    needs stay installed too, so the kept set is what remains *reachable from
    `retain` through `depends_on`*, not merely the retained IDs themselves. It is
    closed over the applied closure in reverse topological order: every
    prerequisite appears earlier in `order`, so visiting `order` backwards makes
    every prerequisite of an already-kept change get visited afterwards, and a
    single pass reaches retention through any chain without a second cycle guard
    beside the one `topological_order` already enforces.

    Closure direction matters: keeping a change never implies keeping its
    dependents, so a rolled-back dependent must not drag its prerequisite along,
    and a prerequisite that was never released is simply skipped. Only the
    retained IDs are seeds, which is why retain cannot revive an unapplied change:
    the final intersection drops anything the journal never recorded as released.
