        "status": "ok",
        "actions": list(ids),
        "units": sum(units_by_id[change_id] for change_id in ids),
    }


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        _environment, action, budget = authorize(request)
        changes = read_changes(request.get("changes"))
        applied = read_journal(request.get("applied", []))
        # Replay identity is established by `read_changes` (duplicates collapsed);
        # from here on every change is distinct, so units are counted per change.
        _validate_graph(changes, applied)
        order = topological_order(changes)
        # Only rollback has retain semantics; reading it for `plan` would turn an
        # ignored field into a new failure mode. A non-rollback action cannot
        # reach this line (it already failed as `unsupported-action`).
        retain = read_retain(request.get("retain")) if action == "rollback" else set()
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if action == "rollback":
        # Rejected after the graph checks because membership can only be judged
        # against a validated `applied` journal and a plannable graph; a retain
        # list naming an ID outside the journal has no release to keep. Checked
        # before any action is built, so a bad list never yields partial actions.
        if not retain <= applied:
            return failure("invalid-retain")
        prerequisites = {row["id"]: row["depends_on"] for row in changes}
        kept = _retained(order, applied, retain, prerequisites)
        # Reverse of the full deterministic order, filtered to the journal: a
        # change that was never released has nothing to unwind, and applied
        # changes still impose the unwind order on each other. Retained changes and
        # the prerequisites they still need drop out of that same order, so the
        # remaining IDs keep their relative reverse order instead of being sorted
        # or moved to either end.
        targets = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in kept]
        return _result(action, targets, units_by_id)

    # Replay point: the journal is subtracted *before* budgeting. An applied
    # change satisfies its dependents' prerequisites and costs no new units, so
    # the budget only has to cover what is actually about to be released.
    targets = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in targets)
    # Checked only after replay: duplicating records must not double the demand,
    # and an applied change must not consume budget it will not spend. The cap is
    # also applied after replay for the same reason: only what is about to be
    # released counts against the budget, never the whole graph.
    if budget_exceeds(action, units, budget):
        return failure("budget-exceeded")
    return _result(action, targets, units_by_id)

