"""Compose policy and journal data into a plan.

Owns the dependency graph, the deterministic execution order and result
assembly. Never reads stdin, parses JSON text, or decides environment/budget
validity; it only consumes data already validated by ``policy``/``journal``.
Order of work is fixed: policy shape -> journal shape -> replay identity ->
graph -> order -> budget -> assembly. That order makes shape errors win over
graph errors and graph errors win over budget errors.
"""
import heapq

from journal import JournalError, dedupe, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def _validate_graph(changes, applied):
    """Fail closed on dangling edges or an unknown replay journal entry."""
    known = {change["id"] for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    # ``applied`` is the caller's persisted journal. An ID that is not in this
    # request cannot be reconciled against the current change set, so it is
    # treated as unknown rather than ignored: silently dropping it would let a
    # stale journal hide a change that actually needs to run (or be reverted).
    for name in applied:
        if name not in known:
            raise JournalError("unknown-dependency")


def _topological_order(changes):
    """Return ids ordered so every dependency precedes its dependents.

    Edges point dependency -> dependent. Kahn's algorithm is driven by a heap
    keyed on the id, so among all currently eligible nodes the lexicographically
    smallest goes first; the order is therefore a total order that does not
    depend on input order. Must emit every node: leftover nodes mean a cycle
    exists somewhere in the graph, even in a part plan/rollback will not emit.
    """
    indegree = {change["id"]: len(set(change["depends_on"])) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        for dependency in set(change["depends_on"]):
            dependents[dependency].append(change["id"])
    ready = [name for name, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependent in dependents[current]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = dedupe(read_changes(request.get("changes")))
        applied = read_applied(request.get("applied", []))
        _validate_graph(changes, applied)
        order = _topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    applied_set = set(applied)
    units_by_id = {change["id"]: change["units"] for change in changes}
    if request["action"] == "rollback":
        # Rollback undoes the full order backwards and only touches steps the
        # journal says were applied; unapplied changes are never reverted.
        # Budget is validated in policy but deliberately does not cap rollback.
        actions = [name for name in reversed(order) if name in applied_set]
    else:
        # Already applied steps satisfy dependencies for later steps but are
        # not emitted, so they never consume the remaining budget.
        actions = [name for name in order if name not in applied_set]
        units = sum(units_by_id[name] for name in actions)
        if units > budget:
            return failure("budget-exceeded")
    return success(actions, sum(units_by_id[name] for name in actions))

